#!/usr/bin/env bash
# Milepost — test, smoke, bump build, archive, export, upload to TestFlight.
#
# The build number lives in project.yml (CURRENT_PROJECT_VERSION) because the
# pbxproj is generated by xcodegen and would be overwritten.
#
#   ./scripts/ship.sh                 # unit tests as the gate
#   SHIP_RUN_UI=1 ./scripts/ship.sh   # unit + UI tests
#   SHIP_SKIP_SMOKE=1 ./scripts/ship.sh
set -euo pipefail

cleanup() {
    pkill -f 'log stream .*altool' 2>/dev/null || true
}
trap cleanup EXIT INT TERM

cd "$(dirname "$0")/.."

if [[ ! -f scripts/asc-config.env ]]; then
    echo "error: scripts/asc-config.env missing. Copy from .example and fill in." >&2
    exit 1
fi

# shellcheck disable=SC1091
source scripts/asc-config.env

if [[ -z "${ASC_APP_ID:-}" ]]; then
    echo "error: ASC_APP_ID is empty. Run scripts/register_in_asc.py first." >&2
    exit 1
fi

PROJECT="Milepost.xcodeproj"
SCHEME="Milepost"
PROJECT_YML="project.yml"
ARCHIVE="build.nosync/Milepost.xcarchive"
EXPORT_DIR="build.nosync/export"
IPA="$EXPORT_DIR/Milepost.ipa"

echo "==> running tests"
if [[ "${SHIP_RUN_UI:-0}" == "1" ]]; then
    ./scripts/run_tests.sh all
else
    ./scripts/run_tests.sh unit
fi

# A green suite does not prove the app starts — XCUITest launches through its
# own harness. Prove a cold launch works before shipping.
if [[ "${SHIP_SKIP_SMOKE:-0}" == "1" ]]; then
    echo "==> skipping smoke test (SHIP_SKIP_SMOKE=1)"
else
    echo "==> smoke-testing a simulator launch"
    ./scripts/smoke_test.sh
fi

current=$(grep -m1 'CURRENT_PROJECT_VERSION:' "$PROJECT_YML" | sed -E 's/.*"([0-9]+)".*/\1/')
next=$((current + 1))
echo "==> bumping build $current -> $next"
sed -i '' "s/CURRENT_PROJECT_VERSION: \"$current\"/CURRENT_PROJECT_VERSION: \"$next\"/" "$PROJECT_YML"

echo "==> regenerating xcodeproj"
./scripts/generate.sh >/dev/null

ASC_AUTH_FLAGS=(
    -authenticationKeyPath "$ASC_KEY_PATH"
    -authenticationKeyID "$ASC_KEY_ID"
    -authenticationKeyIssuerID "$ASC_ISSUER_ID"
)

echo "==> archiving"
rm -rf build.nosync
mkdir -p build.nosync
xcodebuild \
    -project "$PROJECT" \
    -scheme "$SCHEME" \
    -configuration Release \
    -destination "generic/platform=iOS" \
    -archivePath "$ARCHIVE" \
    -allowProvisioningUpdates \
    "${ASC_AUTH_FLAGS[@]}" \
    archive

echo "==> exporting IPA"
xcodebuild \
    -exportArchive \
    -archivePath "$ARCHIVE" \
    -exportPath "$EXPORT_DIR" \
    -exportOptionsPlist ExportOptions.plist \
    -allowProvisioningUpdates \
    "${ASC_AUTH_FLAGS[@]}"

echo "==> uploading to TestFlight"
xcrun altool \
    --upload-app \
    -f "$IPA" \
    -t ios \
    --apiKey "$ASC_KEY_ID" \
    --apiIssuer "$ASC_ISSUER_ID"

echo "==> shipped build $next"
echo "    Processing takes a few minutes before it appears in TestFlight."
